	}
	hours := *req.WeeklyHours
	if hours == nil {
		hours = []weeklyHours{}
	}
	weekMinutes := 7 * 24 * 60
	type interval struct{ start, end int }
	var intervals []interval
	for i, wh := range hours {
		if wh.Weekday < 1 || wh.Weekday > 7 {
			return venue{}, fmt.Errorf("weeklyHours[%d].weekday must be between 1 and 7", i)
		}
		start, ok := parseHHMM(wh.Start)
		if !ok {
			return venue{}, fmt.Errorf("weeklyHours[%d].start must be HH:mm between 00:00 and 23:59", i)
		}
		end, ok := parseHHMM(wh.End)
		if !ok {
			return venue{}, fmt.Errorf("weeklyHours[%d].end must be HH:mm between 00:00 and 23:59", i)
		}
		if start == end {
			return venue{}, fmt.Errorf("weeklyHours[%d].start and end must differ", i)
		}
		base := (wh.Weekday - 1) * 24 * 60
		s := base + start
		e := base + end
		if end <= start {
			e += 24 * 60
		}
		// expand into [0, weekMinutes)
		intervals = append(intervals, interval{s, e})
	}
	// overlap check on circle
	for i := 0; i < len(intervals); i++ {
		for j := i + 1; j < len(intervals); j++ {
			if overlap(intervals[i], intervals[j], weekMinutes) {
				return venue{}, errors.New("weeklyHours intervals must not overlap")
			}
		}
	}
	return venue{Name: name, Capacity: capacity, Timezone: tz, WeeklyHours: hours}, nil
}
