```go
func overlap(a, b interval, week int) bool {
	// expand each into pieces within [0, week)
	pieces := func(iv interval) [][2]int {
		var p [][2]int
		if iv.end <= week {
			p = append(p, [2]int{iv.start, iv.end})
		} else {
			p = append(p, [2]int{iv.start, week})
			p = append(p, [2]int{0, iv.end - week})
		}
		return p
	}
	pa, pb := pieces(a), pieces(b)
	for _, x := range pa {
		for _, y := range pb {
			if x[0] < y[1] && y[0] < x[1] {
				return true
			}
		}
	}
	return false
}
